SELECT COUNT(*) FROM badges as b, comments as c, posts as p, postHistory as ph, users as u WHERE u.Id = c.UserId AND u.Id = b.UserId AND u.Id = ph.UserId AND u.Id = p.OwnerUserId AND b."Date">=CAST('2010-07-27 17:58:45' AS TIMESTAMP) AND b."Date"<=CAST('2014-09-06 17:33:22' AS TIMESTAMP) AND p.PostTypeId=1 AND p.Score<=35 AND p.AnswerCount=1 AND p.CommentCount<=17 AND p.FavoriteCount>=0
